    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 74-year-old male named John presents to the resuscitation bay with sudden-onset substernal chest pressure radiating to the left arm. Vitals are BP 120/76 mmHg, HR 88 bpm, RR 20 rpm, and SpO2 96% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads I, aVL, V5, and V6 with reciprocal ST-depression in leads V1 and V2. Troponin is 9.8 ng/mL. Which of the following is the most appropriate next step in management?', '["Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours"]'::jsonb, 2, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 52-year-old male named David presents to the Emergency Department triage room with sudden-onset substernal chest pressure radiating to the back. Vitals are BP 138/78 mmHg, HR 92 bpm, RR 14 rpm, and SpO2 96% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads I, aVL, V5, and V6 with reciprocal ST-depression in leads I and aVL. Troponin is 9.8 ng/mL. Which of the following is the most appropriate next step in management?', '["Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms", "Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours"]'::jsonb, 2, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 62-year-old male named Christopher presents to the bedside monitor area with sudden-onset substernal chest pressure radiating to the left arm. Vitals are BP 126/82 mmHg, HR 88 bpm, RR 18 rpm, and SpO2 97% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads V1 through V4 with reciprocal ST-depression in leads I and aVL. Troponin is 4.5 ng/mL. Which of the following is the most appropriate next step in management?', '["Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms"]'::jsonb, 1, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 58-year-old male named Nicholas presents to the Emergency Department triage room with sudden-onset substernal chest pressure radiating to the back. Vitals are BP 118/72 mmHg, HR 72 bpm, RR 14 rpm, and SpO2 99% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads I, aVL, V5, and V6 with reciprocal ST-depression in leads II, III, and aVF. Troponin is 4.5 ng/mL. Which of the following is the most appropriate next step in management?', '["Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy"]'::jsonb, 3, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 50-year-old male named Charles presents to the resuscitation bay with sudden-onset substernal chest pressure radiating to the left arm. Vitals are BP 138/84 mmHg, HR 76 bpm, RR 18 rpm, and SpO2 97% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads II, III, and aVF with reciprocal ST-depression in leads I and aVL. Troponin is 1.25 ng/mL. Which of the following is the most appropriate next step in management?', '["Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms"]'::jsonb, 0, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 42-year-old male named Donald presents to the resuscitation bay with sudden-onset substernal chest pressure radiating to the left arm. Vitals are BP 118/84 mmHg, HR 84 bpm, RR 14 rpm, and SpO2 96% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads I, aVL, V5, and V6 with reciprocal ST-depression in leads I and aVL. Troponin is 9.8 ng/mL. Which of the following is the most appropriate next step in management?', '["Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms"]'::jsonb, 1, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 52-year-old male named Michael presents to the resuscitation bay with sudden-onset substernal chest pressure radiating to the left shoulder. Vitals are BP 138/72 mmHg, HR 72 bpm, RR 20 rpm, and SpO2 98% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads I, aVL, V5, and V6 with reciprocal ST-depression in leads I and aVL. Troponin is 7.2 ng/mL. Which of the following is the most appropriate next step in management?', '["Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms", "Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy"]'::jsonb, 2, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 46-year-old female named Cynthia presents to the Emergency Department triage room with sudden-onset substernal chest pressure radiating to the jaw. Vitals are BP 134/84 mmHg, HR 80 bpm, RR 16 rpm, and SpO2 100% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads I, aVL, V5, and V6 with reciprocal ST-depression in leads V1 and V2. Troponin is 4.5 ng/mL. Which of the following is the most appropriate next step in management?', '["Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms"]'::jsonb, 3, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 54-year-old male named David presents to the resuscitation bay with sudden-onset substernal chest pressure radiating to the back. Vitals are BP 120/86 mmHg, HR 72 bpm, RR 18 rpm, and SpO2 98% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads II, III, and aVF with reciprocal ST-depression in leads V1 and V2. Troponin is 9.8 ng/mL. Which of the following is the most appropriate next step in management?', '["Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms", "Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week"]'::jsonb, 1, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 84-year-old female named Susan presents to the Emergency Department triage room with sudden-onset substernal chest pressure radiating to the left shoulder. Vitals are BP 118/72 mmHg, HR 72 bpm, RR 16 rpm, and SpO2 98% on room air. The initial ECG reveals ST-elevation of 2.5 mm in leads V1 through V4 with reciprocal ST-depression in leads II, III, and aVF. Troponin is 7.2 ng/mL. Which of the following is the most appropriate next step in management?', '["Obtain a chest CT angiogram to rule out aortic dissection prior to initiating any antiplatelet therapy", "Administer oral metoprolol 50 mg immediately and repeat the ECG in 4 hours", "Initiate intravenous thrombolysis with tenecteplase as first-line therapy, as PCI is reserved for patients with recurrent symptoms", "Discharge the patient home with sublingual nitroglycerin and outpatient cardiology follow-up within 1 week", "Immediate activation of the cardiac catheterization laboratory for primary percutaneous coronary intervention (PCI) and administration of aspirin and a P2Y12 inhibitor"]'::jsonb, 4, 'Acute ST-elevation myocardial infarction (STEMI) requires immediate reperfusion. For a patient presenting to a PCI-capable hospital, primary percutaneous coronary intervention (PCI) is the gold standard and must be performed within 90 minutes of first medical contact. Initial medical therapy includes dual antiplatelet therapy (DAPT) with aspirin (325 mg chewed) and a P2Y12 inhibitor (e.g., ticagrelor or clopidogrel), anticoagulation (e.g., heparin), and nitrates for pain relief if blood pressure permits and there are no contraindications. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1)'),
    (v_topic_id, 'A 64-year-old male named George is brought to the high-acuity area with severe epigastric pain, nausea, and diaphoresis. Vitals are BP 84/54 mmHg, HR 114 bpm, RR 16 rpm, and SpO2 96% on room air. Lungs are clear to auscultation bilaterally, but jugular venous distension is noted. The ECG shows ST-elevation in leads II, III, and aVF. A right-sided ECG (V4R) reveals 1.5 mm of ST-elevation. Which of the following is the most appropriate initial therapy?', '["Intravenous furosemide 40 mg to reduce preload and relieve pulmonary congestion", "Oral metoprolol succinate 25 mg to decrease myocardial oxygen demand", "Intravenous normal saline bolus (500\u20131000 mL) to increase right ventricular preload and improve cardiac output", "Intravenous nitroglycerin infusion titrated to chest pain resolution", "Sublingual nitroglycerin 0.4 mg followed by intravenous morphine 2 mg for pain control"]'::jsonb, 2, 'Right ventricular (RV) myocardial infarction complicates up to 40% of inferior myocardial infarctions. The classic clinical triad of RV infarction is hypotension, clear lung fields, and jugular venous distension (JVD). RV infarctions are highly preload-dependent because the dysfunctional right ventricle requires high fill pressures to push blood through the pulmonary circulation. Nitrates, loop diuretics, and morphine are absolutely contraindicated as they reduce preload and can precipitate severe, refractory hypotension. The initial treatment for RV infarction-induced hypotension is aggressive volume expansion with intravenous crystalloid boluses (normal saline or lactated Ringer''s) to optimize right ventricular preload. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1; Roberts & Hedges Ch. 12)'),
    (v_topic_id, 'A 80-year-old female named Michelle is brought to the high-acuity area with severe epigastric pain, nausea, and diaphoresis. Vitals are BP 86/50 mmHg, HR 102 bpm, RR 18 rpm, and SpO2 100% on room air. Lungs are clear to auscultation bilaterally, but jugular venous distension is noted. The ECG shows ST-elevation in leads II, III, and aVF. A right-sided ECG (V4R) reveals 1.5 mm of ST-elevation. Which of the following is the most appropriate initial therapy?', '["Sublingual nitroglycerin 0.4 mg followed by intravenous morphine 2 mg for pain control", "Oral metoprolol succinate 25 mg to decrease myocardial oxygen demand", "Intravenous normal saline bolus (500\u20131000 mL) to increase right ventricular preload and improve cardiac output", "Intravenous furosemide 40 mg to reduce preload and relieve pulmonary congestion", "Intravenous nitroglycerin infusion titrated to chest pain resolution"]'::jsonb, 2, 'Right ventricular (RV) myocardial infarction complicates up to 40% of inferior myocardial infarctions. The classic clinical triad of RV infarction is hypotension, clear lung fields, and jugular venous distension (JVD). RV infarctions are highly preload-dependent because the dysfunctional right ventricle requires high fill pressures to push blood through the pulmonary circulation. Nitrates, loop diuretics, and morphine are absolutely contraindicated as they reduce preload and can precipitate severe, refractory hypotension. The initial treatment for RV infarction-induced hypotension is aggressive volume expansion with intravenous crystalloid boluses (normal saline or lactated Ringer''s) to optimize right ventricular preload. (Ref: Tintinalli''s Ch. 48; Step-Up to EM Ch. 2; Case Files: EM Case 1; Roberts & Hedges Ch. 12)'),
